                    dataKey="label"
                    tick={{ fill: "#64748b", fontSize: 10 }}
                    angle={-30}
                    textAnchor="end"
                    height={70}
                  />
                  <YAxis
                    tickFormatter={(v) => `${v}%`}
                    tick={{ fill: "#64748b", fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v: number, _n, p) => [
                      fmtPct(v, 1),
                      (p?.payload as { meter?: string })?.meter ?? "Value",
