    if (regionFocus === "all") return all;
    return all.filter((d) => d.region === regionFocus);
  }, [regionFocus]);

  const ageScatter = useMemo(() => hostAgeScatter(), []);

  const meters = useMemo(() => METER_COMPARE, []);

  return (
    <div
