                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Host age context"
            subtitle="Median old-age dependency of host blocs (UN WPP framing)"
          >
            <div className="h-[340px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={[...HOST_BLOCS]
                    .filter((h) => h.role === "host")
