"use client";

import { useMemo, useState } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  CORRIDOR_BLOCS,
  DEPENDENCE_GEO,
  HEADLINE,
  HOST_AGE_BURDENS,
  HOST_BLOCS,
  METER_COMPARE,
  REGION_RECIPIENTS,
  SOURCE_NOTE,
  dependenceScatter,
  fmtPct,
  fmtUsdBn,
  hostAgeScatter,
} from "@/data/demographic-cash-flows-geography-2026-data";

// viz-types: recipient region bars+pie, host origin bars, corridor bloc ladder, dependence??age scatter, host pension scatter, meter compare | layout: default

type ViewId = "destinations" | "hosts" | "corridors" | "age";
type DestMetric = "dollars" | "share";
type HostFilter = "all" | "host" | "bridge";
type RegionFocus =
  | "all"
  | "South Asia"
  | "Latin America & Caribbean"
  | "East Asia & Pacific"
  | "Middle East & North Africa"
  | "Sub-Saharan Africa"
  | "Europe & Central Asia";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

